解：semaphore full=0;empty=N; //分别代表满/空缓冲区数目;
int mutex=1; //互斥信号量
void reader()
{
    wait(mutex);
    read++;
    wait(full);
    wait(full); //满区有物品
    read();
    signal(empty);
    signal(mutex);
}
void sender()
{
    wait(mutex);
    wait(empty); //有空区
    send();
    signal(full);
    signal(&mutex);
}
void main()
{
    while(true) { reader(); sender(); }
}

